using AcxiomCRM.Data; using AcxiomCRM.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers; [Authorize] public class LeadsController:Controller{private readonly ApplicationDbContext _db;public LeadsController(ApplicationDbContext db)=>_db=db;public async Task<IActionResult>Index(string?search){var q=_db.Leads.AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.LeadName.Contains(search)||x.Email.Contains(search)||x.Status.Contains(search));return View(await q.OrderByDescending(x=>x.LeadId).ToListAsync());}public IActionResult Create()=>View();[HttpPost]public async Task<IActionResult>Create(Lead l){if(ModelState.IsValid){_db.Leads.Add(l);await _db.SaveChangesAsync();_db.AuditLogs.Add(new AuditLog{Action="Create",EntityName="Lead",RecordId=l.LeadId.ToString(),UserId=User.Identity?.Name});await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}return View(l);}}
